/* ---------------- Reveal-on-scroll hook ---------------- */
function useReveal() {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          obs.unobserve(el);
        }
      },
      { threshold: 0.15 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return [ref, visible];
}

function Reveal({ children, className = "", delay = 0 }) {
  const [ref, visible] = useReveal();
  return (
    <div
      ref={ref}
      className={className}
      style={{
        transition: `opacity 0.8s cubic-bezier(0.22,1,0.36,1) ${delay}ms, transform 0.8s cubic-bezier(0.22,1,0.36,1) ${delay}ms`,
        opacity: visible ? 1 : 0,
        transform: visible ? "translateY(0)" : "translateY(28px)",
      }}
    >
      {children}
    </div>
  );
}

/* ---------------- Signature emblem: crossed razor + scissors ---------------- */
function Emblem({ className = "", strokeAnim = false }) {
  return (
    <svg viewBox="0 0 100 100" className={className} fill="none">
      <circle cx="50" cy="50" r="48" stroke="url(#emblemRing)" strokeWidth="1" opacity="0.5" />
      <defs>
        <linearGradient id="emblemRing" x1="0" y1="0" x2="100" y2="100">
          <stop offset="0%" stopColor="#C6A15B" />
          <stop offset="100%" stopColor="#8A6E37" />
        </linearGradient>
      </defs>
      {/* razor */}
      <g>
        <rect x="46" y="18" width="8" height="26" rx="2.5" fill="#E9CD8C" />
        <path d="M46 44 L54 44 L50 60 Z" fill="#C6A15B" />
      </g>
      {/* scissors, crossed */}
      <g transform="rotate(28 50 62)">
        <line x1="50" y1="30" x2="50" y2="78" stroke="#C6A15B" strokeWidth="3" strokeLinecap="round" />
        <circle cx="50" cy="78" r="6" stroke="#C6A15B" strokeWidth="3" fill="none" />
      </g>
      <g transform="rotate(-28 50 62)">
        <line x1="50" y1="30" x2="50" y2="78" stroke="#E9CD8C" strokeWidth="3" strokeLinecap="round" />
        <circle cx="50" cy="78" r="6" stroke="#E9CD8C" strokeWidth="3" fill="none" />
      </g>
    </svg>
  );
}

/* ---------------- Navbar ---------------- */
function Navbar({ onBook }) {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 24);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const handleNav = (href) => {
    setOpen(false);
    const el = document.querySelector(href);
    if (el) el.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <header
      className="fixed top-0 left-0 right-0 z-50 transition-all duration-500"
      style={{
        background: scrolled ? "rgba(10,10,11,0.88)" : "transparent",
        backdropFilter: scrolled ? "blur(14px)" : "none",
        borderBottom: scrolled ? "1px solid rgba(198,161,91,0.18)" : "1px solid transparent",
      }}
    >
      <div className="max-w-7xl mx-auto px-5 md:px-8">
        <div className="flex items-center justify-between h-20">
          <button
            onClick={() => handleNav("#home")}
            className="flex items-center gap-3 group"
            aria-label="Mr.SD Men's Salon & Spa, go to home"
          >
            <Emblem className="w-10 h-10 shrink-0" />
            <span className="flex flex-col items-start leading-tight">
              <span
                className="text-xl tracking-wide"
                style={{ fontFamily: "'Playfair Display', serif", color: "#F4EFE4" }}
              >
                Mr.SD
              </span>
              <span className="text-xs tracking-widest uppercase" style={{ color: "#A39C8E" }}>
                Men's Salon &amp; Spa
              </span>
            </span>
          </button>

          <nav className="hidden md:flex items-center gap-9">
            {NAV_LINKS.map((link) => (
              <button
                key={link.href}
                onClick={() => handleNav(link.href)}
                className="text-sm tracking-wide transition-colors duration-300 relative group"
                style={{ color: "#D8D2C4", fontFamily: "'Manrope', sans-serif" }}
              >
                {link.label}
                <span
                  className="absolute left-0 -bottom-1 w-0 h-px group-hover:w-full transition-all duration-300"
                  style={{ background: "#C6A15B" }}
                />
              </button>
            ))}
          </nav>

          <div className="hidden md:block">
            <button onClick={onBook} className="btn-gold text-sm px-6 py-2.5">
              Book Now
            </button>
          </div>

          <button
            className="md:hidden p-2"
            onClick={() => setOpen((o) => !o)}
            aria-label={open ? "Close menu" : "Open menu"}
          >
            {open ? <X className="w-6 h-6" style={{ color: "#F4EFE4" }} /> : <Menu className="w-6 h-6" style={{ color: "#F4EFE4" }} />}
          </button>
        </div>
      </div>

      {open && (
        <div
          className="md:hidden px-5 pb-6 flex flex-col gap-1"
          style={{ background: "rgba(10,10,11,0.98)", borderTop: "1px solid rgba(198,161,91,0.14)" }}
        >
          {NAV_LINKS.map((link) => (
            <button
              key={link.href}
              onClick={() => handleNav(link.href)}
              className="text-left py-3 text-base"
              style={{ color: "#D8D2C4", fontFamily: "'Manrope', sans-serif", borderBottom: "1px solid rgba(198,161,91,0.08)" }}
            >
              {link.label}
            </button>
          ))}
          <button onClick={() => { setOpen(false); onBook(); }} className="btn-gold text-sm mt-4 py-3">
            Book Now
          </button>
        </div>
      )}
    </header>
  );
}

