/* ---------------- Booking Modal ---------------- */
function BookingModal({ open, onClose }) {
  const [submitted, setSubmitted] = useState(false);
  const [form, setForm] = useState({
    name: "",
    phone: "",
    service: "",
    date: "",
    time: "",
    message: "",
  });

  useEffect(() => {
    if (open) {
      setSubmitted(false);
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }
    return () => {
      document.body.style.overflow = "";
    };
  }, [open]);

  const handleChange = (field) => (e) => setForm((f) => ({ ...f, [field]: e.target.value }));

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
  };

  if (!open) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4"
      style={{ background: "rgba(6,6,7,0.82)", backdropFilter: "blur(6px)" }}
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-lg rounded-2xl p-6 sm:p-8 md:p-10 overflow-y-auto modal-panel"
        style={{ background: "#131315", border: "1px solid rgba(198,161,91,0.25)", maxHeight: "90vh", boxShadow: "0 24px 60px rgba(0,0,0,0.5)" }}
        onClick={(e) => e.stopPropagation()}
      >
        <button
          onClick={onClose}
          className="absolute top-4 right-4 sm:top-5 sm:right-5 p-2 rounded-full transition-colors modal-close-btn"
          style={{ color: "#A39C8E" }}
          aria-label="Close booking form"
        >
          <X className="w-5 h-5" />
        </button>

        {!submitted ? (
          <>
            <Emblem className="w-10 h-10 mb-5" />
            <h3 style={{ fontFamily: "'Playfair Display', serif", fontSize: "1.6rem", color: "#F4EFE4" }}>
              Request Appointment
            </h3>
            <p className="mt-2 text-sm" style={{ color: "#A39C8E", fontFamily: "'Manrope', sans-serif" }}>
              Fill in your details and we'll confirm your slot.
            </p>

            <form onSubmit={handleSubmit} className="mt-7 space-y-4">
              <div>
                <label className="form-label">Name</label>
                <input
                  required
                  type="text"
                  value={form.name}
                  onChange={handleChange("name")}
                  className="form-input"
                  placeholder="Your name"
                />
              </div>
              <div>
                <label className="form-label">Phone Number</label>
                <input
                  required
                  type="tel"
                  value={form.phone}
                  onChange={handleChange("phone")}
                  className="form-input"
                  placeholder="Your phone number"
                />
              </div>
              <div>
                <label className="form-label">Service</label>
                <select required value={form.service} onChange={handleChange("service")} className="form-input">
                  <option value="" disabled>Select a service</option>
                  <option>Men's Haircuts</option>
                  <option>Hair Styling</option>
                  <option>Hair Coloring</option>
                  <option>Spa Treatments</option>
                </select>
              </div>
              <div className="grid grid-cols-2 gap-3 sm:gap-4">
                <div>
                  <label className="form-label">Preferred Date</label>
                  <input
                    required
                    type="date"
                    value={form.date}
                    onChange={handleChange("date")}
                    className="form-input"
                  />
                </div>
                <div>
                  <label className="form-label">Preferred Time</label>
                  <input
                    required
                    type="time"
                    value={form.time}
                    onChange={handleChange("time")}
                    className="form-input"
                  />
                </div>
              </div>
              <div>
                <label className="form-label">Message</label>
                <textarea
                  value={form.message}
                  onChange={handleChange("message")}
                  rows={3}
                  className="form-input resize-none"
                  placeholder="Anything we should know? (optional)"
                />
              </div>

              <button type="submit" className="btn-gold w-full py-3.5 text-sm mt-2">
                Request Appointment
              </button>

              <a
                href={WHATSAPP_LINK}
                target="_blank"
                rel="noopener noreferrer"
                className="btn-outline w-full py-3.5 text-sm mt-1 inline-flex items-center justify-center gap-2"
              >
                <MessageCircle className="w-4 h-4" />
                Or Book via WhatsApp
              </a>
            </form>
          </>
        ) : (
          <div className="text-center py-8">
            <div
              className="w-16 h-16 rounded-full mx-auto flex items-center justify-center mb-6"
              style={{ background: "rgba(198,161,91,0.12)", border: "1px solid rgba(198,161,91,0.3)" }}
            >
              <Calendar className="w-7 h-7" style={{ color: "#C6A15B" }} />
            </div>
            <h3 style={{ fontFamily: "'Playfair Display', serif", fontSize: "1.5rem", color: "#F4EFE4" }}>
              Request Received
            </h3>
            <p className="mt-3 text-sm max-w-xs mx-auto leading-relaxed" style={{ color: "#A39C8E", fontFamily: "'Manrope', sans-serif" }}>
              This is a demo form and hasn't been sent anywhere. To confirm a real appointment right now, please
              call or message us on WhatsApp.
            </p>
            <div className="mt-7 flex flex-col sm:flex-row gap-3 justify-center">
              <a href={`tel:${PHONE_TEL}`} className="btn-outline px-6 py-3 text-sm inline-flex items-center justify-center gap-2">
                <Phone className="w-4 h-4" />
                Call Now
              </a>
              <a href={WHATSAPP_LINK} target="_blank" rel="noopener noreferrer" className="btn-gold px-6 py-3 text-sm inline-flex items-center justify-center gap-2">
                <MessageCircle className="w-4 h-4" />
                WhatsApp Us
              </a>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

